const normalize = (value) => String(value ?? '')
  .replace(/\r\n?/g, '\n')
  .replace(/[\u200B-\u200D\uFEFF]/g, '')
  .replace(/\u00A0/g, ' ')
  .replace(/[\t ]+/g, ' ')
  .replace(/ *\n */g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

const getField = (record, names) => {
  for (const name of names) {
    if (record[name] !== undefined && record[name] !== null) return record[name];
  }
  return undefined;
};

const cleanedItems = [];
const seenContent = new Set();
const seenIds = new Map();
let duplicatesRemoved = 0;

for (const item of $input.all()) {
  const input = item.json ?? {};
  let parsed = input.data ?? input.testCases ?? input.test_cases ?? input;
  if (typeof parsed === 'string') {
    try {
      parsed = JSON.parse(parsed);
    } catch (error) {
      throw new Error(`Extracted test-case JSON is invalid: ${error.message}`);
    }
  }

  const cases = Array.isArray(parsed)
    ? parsed
    : Array.isArray(parsed?.testCases)
      ? parsed.testCases
      : Array.isArray(parsed?.test_cases)
        ? parsed.test_cases
        : Array.isArray(parsed?.cases)
          ? parsed.cases
          : [parsed];
  if (cases.length === 0) throw new Error('The uploaded file contains no test cases.');

  const sourceName = normalize(input.sourceName ?? input['Source Name'] ?? 'uploaded-test-cases.json') || 'uploaded-test-cases.json';

  for (let index = 0; index < cases.length; index++) {
    const testCase = cases[index];
    if (!testCase || typeof testCase !== 'object' || Array.isArray(testCase)) {
      throw new Error(`Test case ${index + 1} must be a JSON object.`);
    }

    const id = normalize(getField(testCase, ['id', 'testCaseId', 'test_case_id', 'Test Case ID', 'TestCaseID']));
    const title = normalize(getField(testCase, ['title', 'name', 'Test Case', 'Test Case Title']));
    const preconditions = normalize(getField(testCase, ['preconditions', 'precondition', 'Preconditions']));
    const rawSteps = getField(testCase, ['steps', 'testSteps', 'test_steps', 'Steps']);
    const expectedResult = normalize(getField(testCase, ['expectedResult', 'expected_result', 'expected', 'Expected Result']));
    const steps = Array.isArray(rawSteps)
      ? rawSteps.map(normalize).filter(Boolean)
      : typeof rawSteps === 'string'
        ? rawSteps.split(/\r?\n|;/).map(normalize).filter(Boolean)
        : [];

    if (!title) throw new Error(`Test case ${index + 1} is missing title.`);
    if (steps.length === 0) throw new Error(`Test case ${id || index + 1} must have at least one step.`);
    if (!expectedResult) throw new Error(`Test case ${id || index + 1} is missing expectedResult.`);

    const contentKey = normalize([title, preconditions, ...steps, expectedResult].join('\n')).toLocaleLowerCase();
    const idKey = id.toLocaleLowerCase();
    if (idKey && seenIds.has(idKey)) {
      if (seenIds.get(idKey) !== contentKey) throw new Error(`Test case ID ${id} is used by different test-case content.`);
      duplicatesRemoved++;
      continue;
    }
    if (seenContent.has(contentKey)) {
      duplicatesRemoved++;
      continue;
    }

    if (idKey) seenIds.set(idKey, contentKey);
    seenContent.add(contentKey);

    const cleanedText = [
      id ? `Test Case ID: ${id}` : null,
      `Title: ${title}`,
      preconditions ? `Preconditions: ${preconditions}` : null,
      `Steps:\n${steps.map((step, stepIndex) => `${stepIndex + 1}. ${step}`).join('\n')}`,
      `Expected Result: ${expectedResult}`
    ].filter(Boolean).join('\n\n');

    cleanedItems.push({
      json: { testCaseId: id || null, title, preconditions, steps, expectedResult, sourceName, cleanedText },
      pairedItem: { item: 0 }
    });
  }
}

if (cleanedItems.length === 0) throw new Error('No unique test cases remain after deduplication.');
for (const item of cleanedItems) item.json.duplicatesRemoved = duplicatesRemoved;
return cleanedItems;
